  let best = 0;
  for (let i = 0; i < s.length; i++) {
    let balance = 0;
    for (let j = i; j < s.length; j++) {
      balance += s[j] === '(' ? 1 : -1;
      if (balance < 0) break;
      if (balance === 0) {
        const len = j - i + 1;
        if (len > best) best = len;
      }
    }
  }
  return best;
