function solve(s) {
  const n = s.length;
  const dp = new Array(n).fill(0);
  let best = 0;
  for (let i = 0; i < n; i++) {
    if (s[i] !== ')') continue;
    if (i >= 1 && s[i - 1] === '(') {
      dp[i] = 2 + (i >= 2 ? dp[i - 2] : 0);
    } else if (i >= 1 && s[i - 1] === ')') {
      const open = i - dp[i - 1] - 1;
      if (open >= 0 && s[open] === '(') {
        dp[i] = dp[i - 1] + 2 + (open >= 1 ? dp[open - 1] : 0);
      }
    }
    if (dp[i] > best) best = dp[i];
  }
  return best;
}
